#include "riscv2x86/csr_runtime.h"
#include <time.h>
static const struct rv2x86_csr_descriptor *find(const struct rv2x86_csr_context*c,uint16_t a){for(uint32_t i=0;i<c->descriptor_count;i++)if(c->descriptors[i].address==a)return &c->descriptors[i];return 0;}
uint64_t rv2x86_read_time(const struct rv2x86_counter_context*c,enum rv2x86_csr_result*r){struct timespec t;if(!c||c->domain!=RV2X86_COUNTER_MONOTONIC_TIME){*r=RV2X86_CSR_UNSUPPORTED;return 0;}if(clock_gettime(CLOCK_MONOTONIC,&t)){*r=RV2X86_CSR_UNSUPPORTED;return 0;}*r=RV2X86_CSR_OK;return (uint64_t)t.tv_sec*1000000000ull+t.tv_nsec;}
enum rv2x86_csr_result rv2x86_csr_read(const struct rv2x86_csr_context*c,uint16_t a,uint64_t*out){const struct rv2x86_csr_descriptor*d=c?find(c,a):0;if(!d||!d->readable)return RV2X86_CSR_DENIED;*out=c->values[a];return RV2X86_CSR_OK;}
static enum rv2x86_csr_result wr(struct rv2x86_csr_context*c,uint16_t a,uint64_t v,uint64_t*old,int mode){const struct rv2x86_csr_descriptor*d=c?find(c,a):0;if(!d||!d->writable)return RV2X86_CSR_DENIED;*old=c->values[a];if(v&~(d->writable_mask|d->warl_mask))return RV2X86_CSR_WARL_REJECTED;v=(mode==1?*old|v:mode==2?*old&~v:v);c->values[a]=(*old&~(d->writable_mask|d->warl_mask))|(v&(d->writable_mask|d->warl_mask));return RV2X86_CSR_OK;}
enum rv2x86_csr_result rv2x86_csr_write(struct rv2x86_csr_context*c,uint16_t a,uint64_t v,uint64_t*o){return wr(c,a,v,o,0);}enum rv2x86_csr_result rv2x86_csr_set_bits(struct rv2x86_csr_context*c,uint16_t a,uint64_t v,uint64_t*o){return wr(c,a,v,o,1);}enum rv2x86_csr_result rv2x86_csr_clear_bits(struct rv2x86_csr_context*c,uint16_t a,uint64_t v,uint64_t*o){return wr(c,a,v,o,2);}
